options.getOption:
const frame = context.panel.data.series[0];
const getVal = (name) => {
  const f = frame.fields.find((fld) => fld.name === name);
  if (!f) return 0;
  const vals = f.values.buffer || f.values;
  return Number(vals[vals.length - 1]) || 0;
};

const indicators = [
  { name: 'VoLTE Drop', max: 100 },
  { name: 'E-RAB SR', max: 100 },
  { name: 'RAN Avail', max: 100 },
  { name: 'RRC SR', max: 100 },
  { name: 'S1 SR', max: 100 },
  { name: 'VoLTE CSSR', max: 100 },
];

const data = indicators.map((i) => getVal(i.name));

return {
  backgroundColor: 'transparent',
  radar: {
    indicator: indicators,
    radius: '52%',
    center: ['50%', '52%'],
    axisName: { color: '#e0e0e0', fontSize: 10 },
    splitArea: { areaStyle: { color: ['transparent'] } },
    splitLine: { lineStyle: { color: 'rgba(255,255,255,0.2)' } },
    axisLine: { lineStyle: { color: 'rgba(255,255,255,0.2)' } },
  },
  series: [
    {
      type: 'radar',
      data: [
        {
          value: data,
          name: 'RAN Status',
          areaStyle: { color: 'rgba(60, 220, 170, 0.35)' },
          lineStyle: { color: '#3cdcaa', width: 2 },
          itemStyle: { color: '#3cdcaa' },
        },
      ],
    },
  ],
};

